import qcodes
import sweep
from typing import Callable, Dict, List, Union
import concurrent

class async_station(sweep.Station):
    def __init__(self, measurement_config: dict={}, basedir: str=None, verbose: bool=True):
        self._ps_by_inst = {}
        self._gains_by_inst = {}
        super().__init__(measurement_config, basedir, verbose)

    def follow_param(self, param, gain: float=1.0):
        self._params.append((param, gain))
        self.logger.debug(f'Follow paramter: {param.full_name}, gain: {gain}')
        if not param.instrument in self._ps_by_inst:
            self._ps_by_inst[param.instrument] = [param]
            self._gains_by_inst[param.instrument] = [gain]
        else:
            self._ps_by_inst[param.instrument].append(param)
            self._gains_by_inst[param.instrument].append(gain)
        return self

    fp = follow_param

    def _measure_by_inst(self, ps):
        return [p() for p in ps]

    def _measure(self) -> List[float]:
        futs_by_inst = {}
        with concurrent.futures.ThreadPoolExecutor(max_workers=len(self._params)) as executor:
            for i, ps in self._ps_by_inst.items():
                futs_by_inst[i] = executor.submit(self._measure_by_inst, ps)

        ret = {}
        for (futs, ps) in zip(futs_by_inst.values(), self._ps_by_inst.values()):
            results = futs.result()
            for res, p in zip(results, ps):
                ret[p] = res

        final_ret = []
        for p, gain in self._params:
            final_ret.append(ret[p] / gain)

        return final_ret

