def top_peaks(f, m, fmin=5, n=5):
    from scipy.signal import find_peaks
    sel = f > fmin
    fs, ms = f[sel], m[sel]
    pk, _ = find_peaks(ms)
    if len(pk) == 0:
        return []
    order = pk[np.argsort(ms[pk])[::-1][:n]]
    return sorted([(round(float(fs[i]), 1), round(float(ms[i]), 2)) for i in order])
